"""Fitness Scorer — Revenue-grounded composite scoring for mutations.

Revenue mode: brier*0.3 + revenue*0.4 + velocity*0.2 + yield*0.1
Fallback mode (< MIN_REVENUE_EVENTS revenue entries): brier*0.5 + yield*0.3 + parse*0.2
"""

import json
import logging
from pathlib import Path
from statistics import mean
from typing import Optional

from .registry import EvolutionRegistry
from .schemas import EvalResult

logger = logging.getLogger(__name__)

# Revenue-grounded weights (active when sufficient revenue data exists)
BRIER_WEIGHT = 0.3
REVENUE_WEIGHT = 0.4
VELOCITY_WEIGHT = 0.2
YIELD_WEIGHT = 0.1

# Fallback weights (used when revenue data insufficient)
FALLBACK_BRIER_WEIGHT = 0.5
FALLBACK_YIELD_WEIGHT = 0.3
FALLBACK_PARSE_WEIGHT = 0.2

MIN_REVENUE_EVENTS = 3
MIN_CASES = 5
PROMOTION_THRESHOLD = 1.15
ROLLBACK_THRESHOLD = 0.20
ROLLBACK_WINDOW = 3
VELOCITY_BASELINE_DAYS = 90

_REPO_ROOT = Path(__file__).resolve().parents[4]
_REVENUE_PATH = _REPO_ROOT / "data" / "calibration" / "revenue-outcomes.jsonl"


class FitnessScorer:
    def __init__(self, registry: EvolutionRegistry):
        self.registry = registry
        self._revenue_cache: Optional[list[dict]] = None
        self._revenue_mode: Optional[bool] = None

    def _load_revenue_data(self) -> list[dict]:
        if self._revenue_cache is not None:
            return self._revenue_cache
        if not _REVENUE_PATH.exists():
            self._revenue_cache = []
            return []
        events = []
        for line in _REVENUE_PATH.read_text(encoding="utf-8").strip().split("\n"):
            if not line.strip():
                continue
            try:
                events.append(json.loads(line))
            except json.JSONDecodeError:
                continue
        self._revenue_cache = events
        return events

    def _is_revenue_mode(self) -> bool:
        if self._revenue_mode is not None:
            return self._revenue_mode
        events = self._load_revenue_data()
        self._revenue_mode = len(events) >= MIN_REVENUE_EVENTS
        if not self._revenue_mode:
            logger.debug("DEGRADED: insufficient revenue data (%d/%d), using analysis-only fitness",
                         len(events), MIN_REVENUE_EVENTS)
        return self._revenue_mode

    def _load_revenue_for_case(self, case_id: str) -> Optional[float]:
        """Load max cumulative revenue signal (0.0-1.0) for a case."""
        events = self._load_revenue_data()
        case_events = [e for e in events if e.get("case_id") == case_id]
        if not case_events:
            return None
        return max(e.get("reward_signal", 0.0) for e in case_events)

    def _compute_velocity(self, case_id: str) -> Optional[float]:
        """Score based on days_since_verdict for first event. Faster = higher score."""
        events = self._load_revenue_data()
        case_events = [e for e in events if e.get("case_id") == case_id]
        if not case_events:
            return None
        days = min(e.get("days_since_verdict", VELOCITY_BASELINE_DAYS) for e in case_events)
        if days <= 7:
            return 1.0
        elif days <= VELOCITY_BASELINE_DAYS:
            return 1.0 - ((days - 7) / (VELOCITY_BASELINE_DAYS - 7))
        else:
            return 0.0

    def compute_fitness(self, variant_id: int) -> Optional[float]:
        """Compute composite fitness — revenue-grounded if data available, else fallback."""
        entries = self.registry.get_fitness_entries(variant_id)
        if not entries:
            return None

        brier_scores = [e.brier_score for e in entries if e.brier_score is not None]
        yields = [e.fact_yield for e in entries]
        parses = [e.parse_success for e in entries]

        if not yields:
            return None

        brier_component = (1.0 - mean(brier_scores)) if brier_scores else 0.5
        yield_component = min(mean(yields) / 3.0, 1.0)
        parse_component = mean(parses)

        if not self._is_revenue_mode():
            return (
                brier_component * FALLBACK_BRIER_WEIGHT
                + yield_component * FALLBACK_YIELD_WEIGHT
                + parse_component * FALLBACK_PARSE_WEIGHT
            )

        # Revenue mode: aggregate revenue signals across all cases this variant touched
        case_ids = list({e.case_id for e in entries})
        revenue_signals = [self._load_revenue_for_case(cid) for cid in case_ids]
        revenue_signals = [r for r in revenue_signals if r is not None]

        velocity_signals = [self._compute_velocity(cid) for cid in case_ids]
        velocity_signals = [v for v in velocity_signals if v is not None]

        revenue_component = mean(revenue_signals) if revenue_signals else 0.0
        velocity_component = mean(velocity_signals) if velocity_signals else 0.5

        return (
            brier_component * BRIER_WEIGHT
            + revenue_component * REVENUE_WEIGHT
            + velocity_component * VELOCITY_WEIGHT
            + yield_component * YIELD_WEIGHT
        )

    def evaluate(self, mutation_id: int) -> EvalResult:
        """Evaluate mutation: PENDING, PROMOTE, or KILL."""
        variants = self.registry.get_variants(mutation_id)
        if not variants:
            return EvalResult(decision="KILL", reason="no variants")

        original = next((v for v in variants if v.variant_index == 0), None)
        if not original:
            return EvalResult(decision="KILL", reason="no original variant")

        if original.cases_tested < MIN_CASES:
            return EvalResult(
                decision="PENDING",
                reason=f"insufficient cases ({original.cases_tested}/{MIN_CASES})",
            )

        scores: dict[int, float] = {}
        for v in variants:
            score = self.compute_fitness(v.id)
            if score is not None:
                scores[v.id] = score

        original_score = scores.get(original.id)
        if original_score is None or original_score == 0.0:
            return EvalResult(decision="PENDING", reason="original not scored yet")

        best_id = None
        best_score = 0.0
        for vid, score in scores.items():
            if vid != original.id and score > best_score:
                best_id = vid
                best_score = score

        if best_id and best_score >= original_score * PROMOTION_THRESHOLD:
            improvement = (best_score - original_score) / original_score
            return EvalResult(
                decision="PROMOTE",
                winner_id=best_id,
                improvement_pct=round(improvement, 4),
                reason=f"variant beats original by {improvement:.1%}",
            )

        return EvalResult(
            decision="KILL",
            reason=f"best={best_score:.3f} < threshold={original_score * PROMOTION_THRESHOLD:.3f}",
        )

    def check_regression(self, mutation_id: int) -> bool:
        """Post-promotion regression check. Returns True if rollback needed."""
        variants = self.registry.get_variants(mutation_id)
        winner = next((v for v in variants if v.is_winner), None)
        original = next((v for v in variants if v.variant_index == 0), None)

        if not winner or not original:
            return False

        winner_entries = self.registry.get_fitness_entries(winner.id)
        if len(winner_entries) < ROLLBACK_WINDOW:
            return False

        recent = winner_entries[-ROLLBACK_WINDOW:]
        recent_yields = [e.fact_yield for e in recent]
        recent_parses = [e.parse_success for e in recent]

        all_entries = self.registry.get_fitness_entries(winner.id)
        pre_promo = all_entries[:-ROLLBACK_WINDOW] if len(all_entries) > ROLLBACK_WINDOW else []

        if not pre_promo:
            return False

        pre_yield = mean([e.fact_yield for e in pre_promo])
        post_yield = mean(recent_yields)

        if pre_yield > 0 and (pre_yield - post_yield) / pre_yield > ROLLBACK_THRESHOLD:
            return True

        pre_parse = mean([e.parse_success for e in pre_promo])
        post_parse = mean(recent_parses)

        if pre_parse > 0 and (pre_parse - post_parse) / pre_parse > ROLLBACK_THRESHOLD:
            return True

        return False

"""Evolution Registry — SQLite persistence for mutations, variants, and fitness tracking."""

import sqlite3
from datetime import datetime, timezone
from pathlib import Path
from typing import Optional

from .schemas import Mutation, Variant, FitnessEntry

ROOT = Path(__file__).resolve().parents[4]
DEFAULT_DB = ROOT / "data" / "evolution" / "evolution-registry.db"

SCHEMA_VERSION = 1


class EvolutionRegistry:
    def __init__(self, db_path: Optional[Path] = None):
        self.db_path = db_path or DEFAULT_DB
        self.db_path.parent.mkdir(parents=True, exist_ok=True)
        self._ensure_tables()

    def _conn(self) -> sqlite3.Connection:
        conn = sqlite3.connect(str(self.db_path))
        conn.execute("PRAGMA journal_mode=WAL")
        conn.execute("PRAGMA foreign_keys=ON")
        return conn

    def _ensure_tables(self):
        with self._conn() as conn:
            conn.executescript("""
                CREATE TABLE IF NOT EXISTS schema_meta (
                    key TEXT PRIMARY KEY,
                    value TEXT NOT NULL
                );

                CREATE TABLE IF NOT EXISTS mutations (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    created_at TEXT NOT NULL,
                    component TEXT NOT NULL,
                    target_path TEXT NOT NULL,
                    parent_id INTEGER REFERENCES mutations(id),
                    variant_count INTEGER DEFAULT 0,
                    status TEXT DEFAULT 'testing',
                    fitness_before REAL,
                    fitness_after REAL,
                    improvement_pct REAL,
                    promoted_at TEXT,
                    killed_at TEXT
                );

                CREATE TABLE IF NOT EXISTS variants (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    mutation_id INTEGER NOT NULL REFERENCES mutations(id),
                    variant_index INTEGER NOT NULL,
                    content TEXT NOT NULL,
                    fitness_score REAL,
                    cases_tested INTEGER DEFAULT 0,
                    is_winner INTEGER DEFAULT 0
                );

                CREATE TABLE IF NOT EXISTS fitness_log (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    variant_id INTEGER NOT NULL REFERENCES variants(id),
                    case_id TEXT NOT NULL,
                    brier_score REAL,
                    fact_yield REAL NOT NULL,
                    parse_success REAL NOT NULL,
                    timestamp TEXT NOT NULL
                );

                CREATE INDEX IF NOT EXISTS idx_mutations_component
                    ON mutations(component);
                CREATE INDEX IF NOT EXISTS idx_mutations_status
                    ON mutations(status);
                CREATE INDEX IF NOT EXISTS idx_variants_mutation
                    ON variants(mutation_id);
                CREATE INDEX IF NOT EXISTS idx_fitness_variant
                    ON fitness_log(variant_id);
                CREATE INDEX IF NOT EXISTS idx_fitness_case
                    ON fitness_log(case_id);
            """)
            conn.execute(
                "INSERT OR IGNORE INTO schema_meta (key, value) VALUES (?, ?)",
                ("version", str(SCHEMA_VERSION))
            )

    def _now(self) -> str:
        return datetime.now(timezone.utc).isoformat()

    # --- Mutations ---

    def create_mutation(
        self, component: str, target_path: str, parent_id: Optional[int] = None
    ) -> Mutation:
        now = self._now()
        with self._conn() as conn:
            cursor = conn.execute(
                "INSERT INTO mutations (created_at, component, target_path, parent_id, status) "
                "VALUES (?, ?, ?, ?, 'testing')",
                (now, component, target_path, parent_id),
            )
            mid = cursor.lastrowid
        return Mutation(
            id=mid, created_at=now, component=component,
            target_path=target_path, parent_id=parent_id,
            variant_count=0, status="testing",
            fitness_before=None, fitness_after=None, improvement_pct=None,
        )

    def get_mutation(self, mutation_id: int) -> Optional[Mutation]:
        with self._conn() as conn:
            row = conn.execute(
                "SELECT * FROM mutations WHERE id=?", (mutation_id,)
            ).fetchone()
        if not row:
            return None
        return self._row_to_mutation(row)

    def get_active_mutations(self, component: Optional[str] = None) -> list[Mutation]:
        with self._conn() as conn:
            if component:
                rows = conn.execute(
                    "SELECT * FROM mutations WHERE status='testing' AND component=?",
                    (component,),
                ).fetchall()
            else:
                rows = conn.execute(
                    "SELECT * FROM mutations WHERE status='testing'"
                ).fetchall()
        return [self._row_to_mutation(r) for r in rows]

    def get_recently_promoted(self, days: int = 30) -> list[Mutation]:
        from datetime import timedelta
        cutoff = (datetime.now(timezone.utc) - timedelta(days=days)).isoformat()
        with self._conn() as conn:
            rows = conn.execute(
                "SELECT * FROM mutations WHERE status='promoted' AND promoted_at >= ? "
                "ORDER BY promoted_at DESC LIMIT 20",
                (cutoff,),
            ).fetchall()
        return [self._row_to_mutation(r) for r in rows]

    def get_lineage(self, mutation_id: int, depth: int = 10) -> list[Mutation]:
        chain = []
        current_id = mutation_id
        for _ in range(depth):
            m = self.get_mutation(current_id)
            if not m:
                break
            chain.append(m)
            if not m.parent_id:
                break
            current_id = m.parent_id
        return chain

    # --- Variants ---

    def add_variant(self, mutation_id: int, index: int, content: str) -> Variant:
        with self._conn() as conn:
            cursor = conn.execute(
                "INSERT INTO variants (mutation_id, variant_index, content) VALUES (?, ?, ?)",
                (mutation_id, index, content),
            )
            vid = cursor.lastrowid
            conn.execute(
                "UPDATE mutations SET variant_count = variant_count + 1 WHERE id=?",
                (mutation_id,),
            )
        return Variant(
            id=vid, mutation_id=mutation_id, variant_index=index,
            content=content, fitness_score=None, cases_tested=0, is_winner=False,
        )

    def get_variants(self, mutation_id: int) -> list[Variant]:
        with self._conn() as conn:
            rows = conn.execute(
                "SELECT * FROM variants WHERE mutation_id=? ORDER BY variant_index",
                (mutation_id,),
            ).fetchall()
        return [self._row_to_variant(r) for r in rows]

    def get_variant(self, variant_id: int) -> Optional[Variant]:
        with self._conn() as conn:
            row = conn.execute(
                "SELECT * FROM variants WHERE id=?", (variant_id,)
            ).fetchone()
        if not row:
            return None
        return self._row_to_variant(row)

    def get_variant_by_index(self, mutation_id: int, index: int) -> Optional[Variant]:
        with self._conn() as conn:
            row = conn.execute(
                "SELECT * FROM variants WHERE mutation_id=? AND variant_index=?",
                (mutation_id, index),
            ).fetchone()
        if not row:
            return None
        return self._row_to_variant(row)

    # --- Fitness ---

    def log_fitness(
        self, variant_id: int, case_id: str,
        brier: Optional[float], fact_yield: float, parse_success: float
    ) -> FitnessEntry:
        now = self._now()
        with self._conn() as conn:
            cursor = conn.execute(
                "INSERT INTO fitness_log (variant_id, case_id, brier_score, fact_yield, parse_success, timestamp) "
                "VALUES (?, ?, ?, ?, ?, ?)",
                (variant_id, case_id, brier, fact_yield, parse_success, now),
            )
            fid = cursor.lastrowid
            conn.execute(
                "UPDATE variants SET cases_tested = cases_tested + 1 WHERE id=?",
                (variant_id,),
            )
        return FitnessEntry(
            id=fid, variant_id=variant_id, case_id=case_id,
            brier_score=brier, fact_yield=fact_yield,
            parse_success=parse_success, timestamp=now,
        )

    def get_fitness_entries(self, variant_id: int) -> list[FitnessEntry]:
        with self._conn() as conn:
            rows = conn.execute(
                "SELECT * FROM fitness_log WHERE variant_id=? ORDER BY timestamp",
                (variant_id,),
            ).fetchall()
        return [self._row_to_fitness(r) for r in rows]

    def update_brier_for_case(self, case_id: str, brier_score: float):
        with self._conn() as conn:
            conn.execute(
                "UPDATE fitness_log SET brier_score=? WHERE case_id=? AND brier_score IS NULL",
                (brier_score, case_id),
            )

    # --- Status transitions ---

    def promote_variant(self, variant_id: int):
        now = self._now()
        with self._conn() as conn:
            row = conn.execute(
                "SELECT mutation_id, fitness_score FROM variants WHERE id=?", (variant_id,)
            ).fetchone()
            if not row:
                return
            mutation_id, fitness = row
            conn.execute(
                "UPDATE variants SET is_winner=1 WHERE id=?", (variant_id,)
            )
            conn.execute(
                "UPDATE mutations SET status='promoted', promoted_at=?, fitness_after=? WHERE id=?",
                (now, fitness, mutation_id),
            )

    def kill_mutation(self, mutation_id: int):
        now = self._now()
        with self._conn() as conn:
            conn.execute(
                "UPDATE mutations SET status='killed', killed_at=? WHERE id=?",
                (now, mutation_id),
            )

    def rollback_mutation(self, mutation_id: int):
        now = self._now()
        with self._conn() as conn:
            conn.execute(
                "UPDATE mutations SET status='rolled_back', killed_at=? WHERE id=?",
                (now, mutation_id),
            )
            conn.execute(
                "UPDATE variants SET is_winner=0 WHERE mutation_id=?", (mutation_id,)
            )

    # --- Row mappers ---

    def _row_to_mutation(self, row: tuple) -> Mutation:
        return Mutation(
            id=row[0], created_at=row[1], component=row[2],
            target_path=row[3], parent_id=row[4], variant_count=row[5],
            status=row[6], fitness_before=row[7], fitness_after=row[8],
            improvement_pct=row[9], promoted_at=row[10], killed_at=row[11],
        )

    def _row_to_variant(self, row: tuple) -> Variant:
        return Variant(
            id=row[0], mutation_id=row[1], variant_index=row[2],
            content=row[3], fitness_score=row[4], cases_tested=row[5],
            is_winner=bool(row[6]),
        )

    def _row_to_fitness(self, row: tuple) -> FitnessEntry:
        return FitnessEntry(
            id=row[0], variant_id=row[1], case_id=row[2],
            brier_score=row[3], fact_yield=row[4], parse_success=row[5],
            timestamp=row[6],
        )

"""
replay_engine.py — Replay completed verdicts through alternative strategies.

Zero extra API cost: re-scores the same agent outputs with different rubric/weights/formula.
"""

from __future__ import annotations

import json
import logging
import math
from dataclasses import dataclass, field
from pathlib import Path
from typing import Optional

from .schema import Strategy

logger = logging.getLogger(__name__)

_REPO_ROOT = Path(__file__).resolve().parents[5]
_TRACES_PATH = _REPO_ROOT / "data" / "traces"


@dataclass
class CounterfactualVerdict:
    strategy_id: str
    strategy_name: str
    case_id: str
    score: float
    verdict: str  # "GO" | "NO-GO" | "CONDITIONAL"
    dimension_scores: dict[str, float] = field(default_factory=dict)
    confidence: float = 0.0


class ReplayEngine:
    def __init__(self, traces_path: Optional[Path] = None):
        self.traces_path = Path(traces_path or _TRACES_PATH)

    def replay_case(
        self, case_id: str, strategies: list[Strategy]
    ) -> dict[str, CounterfactualVerdict]:
        """
        Replay a completed case through multiple strategies.
        Returns map of strategy_id -> counterfactual verdict.
        """
        trace = self._load_trace(case_id)
        if trace is None:
            logger.warning("No trace found for case %s", case_id)
            return {}

        agent_outputs = trace.get("agent_outputs", {})
        signals = trace.get("signals", {})

        results = {}
        for strategy in strategies:
            verdict = self._score_with_strategy(strategy, agent_outputs, signals)
            verdict.case_id = case_id
            results[strategy.id] = verdict

        return results

    def _score_with_strategy(
        self,
        strategy: Strategy,
        agent_outputs: dict,
        signals: dict,
    ) -> CounterfactualVerdict:
        """Apply strategy's rubric/formula to agent outputs."""
        dimension_scores = self._extract_dimension_scores(
            agent_outputs, signals, strategy.mountain_rubric
        )

        if strategy.scoring_formula == "weighted_sum":
            final_score = sum(
                dimension_scores.get(dim, 0.0) * weight
                for dim, weight in strategy.mountain_rubric.items()
            )
        elif strategy.scoring_formula == "min_gate":
            scores = [dimension_scores.get(dim, 0.0) for dim in strategy.mountain_rubric]
            final_score = min(scores) if scores else 0.0
        elif strategy.scoring_formula == "bayesian_posterior":
            final_score = self._bayesian_aggregate(dimension_scores, strategy.mountain_rubric)
        else:
            final_score = sum(dimension_scores.values()) / max(len(dimension_scores), 1)

        confidence = self._compute_confidence(agent_outputs, strategy)

        if final_score >= 7.5:
            verdict_label = "GO"
        elif final_score >= 5.0:
            verdict_label = "CONDITIONAL"
        else:
            verdict_label = "NO-GO"

        return CounterfactualVerdict(
            strategy_id=strategy.id,
            strategy_name=strategy.name,
            case_id="",
            score=round(final_score, 2),
            verdict=verdict_label,
            dimension_scores=dimension_scores,
            confidence=round(confidence, 3),
        )

    def _extract_dimension_scores(
        self,
        agent_outputs: dict,
        signals: dict,
        rubric: dict[str, float],
    ) -> dict[str, float]:
        """Extract per-dimension scores from agent outputs."""
        scores = {}
        for dim in rubric:
            dim_scores = []
            for agent_id, output in agent_outputs.items():
                if isinstance(output, dict):
                    agent_scores = output.get("dimension_scores", output.get("scores", {}))
                    if dim in agent_scores:
                        dim_scores.append(agent_scores[dim])
            if dim_scores:
                scores[dim] = sum(dim_scores) / len(dim_scores)
            else:
                scores[dim] = signals.get(f"{dim}_score", 5.0)
        return scores

    def _bayesian_aggregate(
        self, scores: dict[str, float], weights: dict[str, float]
    ) -> float:
        """Bayesian-inspired aggregation: log-odds weighted combination."""
        log_odds_sum = 0.0
        weight_sum = 0.0
        for dim, weight in weights.items():
            score = scores.get(dim, 5.0)
            p = max(0.01, min(0.99, score / 10.0))
            log_odds = math.log(p / (1 - p))
            log_odds_sum += log_odds * weight
            weight_sum += weight

        if weight_sum == 0:
            return 5.0
        avg_log_odds = log_odds_sum / weight_sum
        p_final = 1.0 / (1.0 + math.exp(-avg_log_odds))
        return p_final * 10.0

    def _compute_confidence(self, agent_outputs: dict, strategy: Strategy) -> float:
        """Compute confidence based on agent coverage."""
        expected = set(strategy.wave1_agents + strategy.wave2_agents)
        actual = set(agent_outputs.keys())
        coverage = len(expected & actual) / max(len(expected), 1)

        if strategy.confidence_aggregation == "min_confidence":
            confidences = []
            for output in agent_outputs.values():
                if isinstance(output, dict):
                    c = output.get("confidence", 0.5)
                    confidences.append(c)
            return min(confidences) if confidences else coverage
        elif strategy.confidence_aggregation == "weighted_average":
            confidences = []
            for output in agent_outputs.values():
                if isinstance(output, dict):
                    confidences.append(output.get("confidence", 0.5))
            return sum(confidences) / max(len(confidences), 1) if confidences else coverage
        else:
            return coverage

    def _load_trace(self, case_id: str) -> Optional[dict]:
        """Load trace data for a case."""
        trace_file = self.traces_path / f"{case_id}.json"
        if trace_file.exists():
            try:
                return json.loads(trace_file.read_text(encoding="utf-8"))
            except (json.JSONDecodeError, OSError):
                pass

        trace_dir = self.traces_path / case_id
        if trace_dir.is_dir():
            combined = {"agent_outputs": {}, "signals": {}}
            for f in trace_dir.glob("*.json"):
                try:
                    data = json.loads(f.read_text(encoding="utf-8"))
                    if "agent_id" in data:
                        combined["agent_outputs"][data["agent_id"]] = data
                    elif "signals" in data:
                        combined["signals"].update(data["signals"])
                except (json.JSONDecodeError, OSError):
                    continue
            if combined["agent_outputs"]:
                return combined

        return None

