"""Execution Fitness — scores execution templates by real deal outcomes."""

from __future__ import annotations

import json
import logging
from pathlib import Path
from typing import Optional

from .registry import EvolutionRegistry

logger = logging.getLogger(__name__)

_REPO_ROOT = Path(__file__).resolve().parents[4]
_REVENUE_PATH = _REPO_ROOT / "data" / "calibration" / "revenue-outcomes.jsonl"
_PIPELINE_PATH = _REPO_ROOT / "data" / "deals" / "deal-pipeline.json"

MIN_CASES_FOR_SCORE = 3


class ExecutionFitness:
    """Scores execution templates by real outcomes from deal pipeline."""

    def __init__(self, registry: EvolutionRegistry):
        self.registry = registry

    def _load_deals_with_template(self, variant_id: int) -> list[dict]:
        """Find deals that used a specific template variant."""
        if not _PIPELINE_PATH.exists():
            return []
        try:
            data = json.loads(_PIPELINE_PATH.read_text(encoding="utf-8"))
        except (json.JSONDecodeError, OSError):
            return []
        return [
            d for d in data.get("pipeline", [])
            if d.get("template_variant_id") == variant_id
        ]

    def _load_revenue_events_for_case(self, case_id: str) -> list[dict]:
        if not _REVENUE_PATH.exists():
            return []
        events = []
        for line in _REVENUE_PATH.read_text(encoding="utf-8").strip().split("\n"):
            if not line.strip():
                continue
            try:
                e = json.loads(line)
                if e.get("case_id") == case_id:
                    events.append(e)
            except json.JSONDecodeError:
                continue
        return events

    def score_outreach(self, variant_id: int) -> Optional[float]:
        """Response rate when this outreach template was used."""
        deals = self._load_deals_with_template(variant_id)
        if len(deals) < MIN_CASES_FOR_SCORE:
            return None
        responded = sum(1 for d in deals if d.get("response_received", False))
        return responded / len(deals)

    def score_pricing(self, variant_id: int) -> Optional[float]:
        """Close rate when this pricing frame was presented."""
        deals = self._load_deals_with_template(variant_id)
        if len(deals) < MIN_CASES_FOR_SCORE:
            return None
        closed = sum(1 for d in deals if d.get("stage") in ("closed", "paid"))
        return closed / len(deals)

    def score_negotiation(self, variant_id: int) -> Optional[float]:
        """Average margin percentage when this negotiation tactic was applied."""
        deals = self._load_deals_with_template(variant_id)
        if len(deals) < MIN_CASES_FOR_SCORE:
            return None
        margins = [d.get("final_margin_pct", 0.0) for d in deals if d.get("final_margin_pct") is not None]
        if not margins:
            return None
        return min(1.0, sum(margins) / len(margins))

    def score(self, variant_id: int, category: str) -> Optional[float]:
        """Route to category-specific scorer."""
        if category == "outreach":
            return self.score_outreach(variant_id)
        elif category == "pricing":
            return self.score_pricing(variant_id)
        elif category == "negotiation":
            return self.score_negotiation(variant_id)
        return None

